def check_log_for_errors(file_list):
    error_count = 0
    for file_path in file_list:
        try:
            f = open(file_path, 'r')
            content = f.read()
            if "ERROR" in content:
                error_count += 1
            # Missing close()
        except FileNotFoundError:
            continue
    return error_count

